using System.IO;using System.Text.Json;using VisionCore;using VisionFramework;
namespace VisionPlugins.ImageBinary;
// Group.xml RoiSelect/InheritWay/ExternRoiSelect/Assist0/SelectWay. Transport names are managed contracts.
public static class BinaryRegionResolver{
 public static readonly string[] RectangleFields=["ROICenterX","ROICenterY","ROIWidth","ROIHeight","ROIAngle"];
 public static readonly string[] CircleFields=["ROIAnnulusCenterX","ROIAnnulusCenterY","ROIAnnulusInnerRadius","ROIAnnulusOuterRadius","ROIAnnulusStartAngle","ROIAnnulusAngleExtend"];
 public static readonly string[] FixtureFields=["BaseX","BaseY","Angle","ScaleX","ScaleY","RunPointBaseX","RunPointBaseY","RunAngle","RunScaleX","RunScaleY"];
 public static readonly string[] NumericFields=RectangleFields.Concat(CircleFields).Concat(FixtureFields).ToArray();
 static int Mode(ModuleExecutionContext c,string name,int fallback=0)=>c.Parameters.TryGetValue(name,out var p)?p.GetInt32():fallback;
 static double Number(ModuleExecutionContext c,string name){if(c.Inputs.TryGetValue(name,out var input))return input.As<double>();return c.Parameters.TryGetValue(name,out var p)?p.GetDouble():throw new InvalidDataException("缺少区域参数："+name);}
 public static IReadOnlyList<RoiDocument> Resolve(ModuleExecutionContext c,int width,int height){var result=new List<RoiDocument>();if(Mode(c,"RoiSelect")==0)result.AddRange(c.Rois.Where(r=>!r.Exclusion));else{int way=Mode(c,"InheritWay");if(way is 0 or 2){var inherited=c.Input<RoiRegionValue>(way==0?"Region":"Region2").Regions;if(inherited.Count==0)throw new InvalidDataException("继承区域为空。");foreach(var r in inherited){bool compatible=way==0?r.Kind==RoiKind.Rectangle:r.Kind is RoiKind.SectorRing or RoiKind.Annulus or RoiKind.Sector;if(!compatible||r.Exclusion)throw new InvalidDataException("继承区域类型与继承方式不符。");result.Add(r.Kind==RoiKind.Annulus?r with{Kind=RoiKind.SectorRing}:r);}}else if(way==1)result.Add(new("inherited-rectangle",RoiKind.Rectangle,Number(c,RectangleFields[0]),Number(c,RectangleFields[1]),Number(c,RectangleFields[2]),Number(c,RectangleFields[3]),AngleDegrees:Number(c,RectangleFields[4])));else if(way==3){double sweep=Number(c,CircleFields[5]);result.Add(new("inherited-annular",sweep>=360?RoiKind.SectorRing:RoiKind.Sector,Number(c,CircleFields[0]),Number(c,CircleFields[1]),Radius:Number(c,CircleFields[3]),InnerRadius:Number(c,CircleFields[2])){Shape=new(StartAngle:Number(c,CircleFields[4]),SweepAngle:sweep)});}else throw new InvalidDataException("未知继承方式。");}
 if(Mode(c,"ExternRoiSelect")==0)result.AddRange(c.Rois.Where(r=>r.Exclusion));else{foreach(var r in c.Input<RoiRegionValue>("InputBlindRegion").Regions){if(r.Kind!=RoiKind.Polygon)throw new InvalidDataException("继承屏蔽区必须是多边形。");result.Add(r with{Exclusion=true});}}
 if(result.Any(r=>r.CoordinateSpace==RoiCoordinateSpace.Fixture)&&(!c.Parameters.TryGetValue("Assist0",out var enabled)||!enabled.GetBoolean()))throw new InvalidDataException("继承Fixture区域需要启用位置修正。");RoiGeometry.ValidateForEditor(result,ImageBinaryPlugin.RoiCapabilities);return result.Select(r=>r.CoordinateSpace==RoiCoordinateSpace.Fixture?r with{CoordinateSpace=RoiCoordinateSpace.ImagePixels}:RoiGeometry.ToPixels(r,width,height)).ToArray();}
 public static FixtureValue? Fixture(ModuleExecutionContext c){if(!c.Parameters.TryGetValue("Assist0",out var enabled)||!enabled.GetBoolean()){if(c.Rois.Any(r=>r.CoordinateSpace==RoiCoordinateSpace.Fixture))throw new InvalidDataException("Fixture坐标区域需要启用位置修正。");return null;}int mode=Mode(c,"SelectWay");if(mode==0)return c.Input<FixtureValue>("CorrectInfo");FixturePose Pose(int offset){var point=mode==1?c.Input<Point2>(offset==0?"OriginPoint":"RunPoint"):new Point2(Number(c,FixtureFields[offset]),Number(c,FixtureFields[offset+1]));return new(point.X,point.Y,Number(c,FixtureFields[offset+2]),Number(c,FixtureFields[offset+3]),Number(c,FixtureFields[offset+4]));}return new(Pose(0),Pose(5));}
 public static byte[] Mask(ModuleExecutionContext c,int width,int height,CancellationToken token){var fixture=Fixture(c);var regions=Resolve(c,width,height);var mask=RoiRasterizer.CreateMask(regions,width,height,token);return fixture is null?mask:fixture.WarpMask(mask,width,height,token);}
}
